VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStopNC : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Run : BOOL := FALSE;
    ResetRequired : BOOL := TRUE;
END_VAR

